import collections
import random
from queue import PriorityQueue

def task_func(number_teams=5):
    if not isinstance(number_teams, int) or isinstance(number_teams, bool):
        raise TypeError("number_teams must be an integer")
    if number_teams < 0:
        raise ValueError("number_teams must be non-negative")

    ranking = {
        f"Team {i}": random.randint(0, 100)
        for i in range(1, number_teams + 1)
    }

    return collections.OrderedDict(
        sorted(ranking.items(), key=lambda item: item[1], reverse=True)
    )
